// Clean up the agent response
let response = $input.all()[0].json;

// Extract the actual content from nested structure
function extractContent(obj) {
  if (typeof obj === 'string') return obj;

  // Try common content keys
  if (obj.output) return obj.output;
  if (obj.text) return obj.text;
  if (obj.content) return obj.content;
  if (obj.response) return obj.response;

  // If it's an array, get the first item
  if (Array.isArray(obj) && obj.length > 0) {
    return extractContent(obj[0]);
  }

  // If it's an object, look for content in nested values
  for (let key in obj) {
    if (typeof obj[key] === 'string' && obj[key].length > 10) {
      return obj[key];
    }
    if (typeof obj[key] === 'object') {
      let nested = extractContent(obj[key]);
      if (nested && typeof nested === 'string') return nested;
    }
  }

  return JSON.stringify(obj, null, 2);
}

let cleanResponse = extractContent(response);

return [{ 
  json: { 
    response: cleanResponse,
    status: "success"
  } 
}];

